public static TFMRegistrationCollectorInteger IntegerStep(
                                            int     _id,
                                            str     _name,
                                            str     _header,
                                            str     _label,
                                            str     _helpLabel,
                                            boolean _performCalculation = false,
                                            str     _defaultValue = '',
                                            int     _minValue = minInt(),
                                            int     _maxValue = maxInt(),
                                            int     _length = 14,
                                            str     _eanAI = '')
{
    TFMRegistrationCollectorInteger collector = new TFMRegistrationCollectorInteger(_id,_name,_header,_label,_helpLabel);
    collector.parmPerformCalculation(_performCalculation);
    collector.parmDefaultValue(_defaultValue);
    collector.parmMinValue(_minValue);
    collector.parmmaxValue(_maxValue);
    collector.parmLength(_length);
    collector.parmEanAI(_eanAI);
    return collector;
}

/// <summary>
/// Builds a registration collector for deciaml steps
/// </summary>
/// <param name="Xmldoc"></param>
/// <param name="stepsElement"></param>
/// <param name="id"></param>
/// <param name="name"></param>
/// <param name="header"></param>
/// <param name="label"></param>
/// <param name="helpLabel"></param>
/// <param name="performCalculation">
/// controlles whether the device will accept math expresions like 1.2+1.3 as input
/// </param>
/// <param name="defaultValue"></param>
/// <param name="minValue"></param>
/// <param name="maxValue"></param>
/// <param name="length"></param>
/// <param name="GS1valueId"></param>
/// identifiers for GS1-barcode prefixes
/// </param>
public server static Map IntegerStepMap(
                                            int _id,
                                            str _name,
                                            str _header,
                                            str _label,
                                            str _helpLabel,
                                            boolean _performCalculation = false,
                                            str _defaultValue = '',
                                            int _minValue = -100000000,
                                            int _maxValue = 100000000,
                                            int _length = 14,
                                            str _eanAI = '')
{
    return TFMRegistrationCollectorInteger::IntegerStep(_id,_name, _header, _label, _helpLabel, _performCalculation,_defaultValue,_minValue,_maxValue, _length, _eanAI).getMap();


}

